# -*- coding: utf-8 -*- import os, sys, json, subprocess, numpy as np, soundfile as sf import whisper  sys.path.append(r"E:\VideoTranslator_Project") from clone_dubber import VideoCloneDubber  def run_v52_breath_protector():     print(f"\n[V52.1-Protector] 正在执行【尾音保全】手术 (2:00 之后)...")          script_p = r"E:\VideoTranslator_Project\separated_audio\V51_CALIBRATED_SCRIPT.json"     with open(script_p, "r", encoding="utf-8") as f: data = json.load(f)          role_lib_p = r"E:\VideoTranslator_Project\temp_factory\v9_role_library.json"     with open(role_lib_p, "r") as f: seed_p = json.load(f)['SPEAKER_00']['wav']          db = VideoCloneDubber()     auditor = whisper.load_model("base")      for i in range(15, len(data)):         item = data[i]         # 1. 文本强化：末尾加长句号，引导自然呼气         safe_text = item['zh'].strip() + "。"          print(f"  -> 正在渲染: {safe_text}")                  wav = db.model.generate(text=safe_text, reference_wav_path=seed_p, inference_timesteps=50)         temp_raw = f"E:\\VideoTranslator_Project\\temp_factory\\v52_raw_{i}.wav"         sf.write(temp_raw, wav, db.sample_rate)                  # 2. 审计与保护         res = auditor.transcribe(temp_raw, verbose=False)         last_seg_end = res['segments'][-1]['end'] if res['segments'] else len(wav)/db.sample_rate                  # --- 核心改进：安全缓冲区 ---         # 增加 0.25s 的保护时间，确保不截字         protected_end = last_seg_end + 0.25                  print(f"     ✅ 检出结束点: {last_seg_end:.2f}s | 保护性截断点: {protected_end:.2f}s")                  final_p = f"E:\\VideoTranslator_Project\\temp_factory\\v52_fixed_{i}.wav"         FFMPEG = r"C:\Users\Administrator\miniconda3\envs\blackwell_env\Lib\site-packages\static_ffmpeg\bin\win32\ffmpeg.exe"                  # 3. 执行柔和淡出 (st={last_seg_end} 意味着从字念完的一刻开始渐弱，正好覆盖幻觉音)         cmd_v52 = [             FFMPEG, "-y", "-i", temp_raw,             "-af", f"atrim=end={protected_end},asetpts=PTS-STARTPTS,afade=t=out:st={last_seg_end}:d=0.2",             final_p         ]         subprocess.run(cmd_v52, check=True, capture_output=True)         item['v52_path'] = final_p      # 合成局部审计视频 (2:00-End)     test_video = r"E:\VideoTranslator_Project\output_final\V52_FINAL_TAIL_FIX.mp4"     # ... 此处逻辑同前，缝合回原视频片段 ...     # 为了让您听得最准，我先直接产出一个 WAV     test_wav = r"E:\VideoTranslator_Project\output_final\V52_END_VOICE_AUDIT.wav"     input_args = []     filter_parts = []     for idx, i in enumerate(range(15, len(data))):         input_args.extend(["-i", data[i]['v52_path']])         delay = int((data[i]['start'] - 120) * 1000)         filter_parts.append(f"[{idx}:a]adelay={delay}|{delay}[a{idx}]")          mix_str = "".join([f"[a{k}]" for k in range(len(input_args)//2)]) + f"amix=inputs={len(input_args)//2}"     subprocess.run([FFMPEG, "-y"] + input_args + ["-filter_complex", ";".join(filter_parts) + ";" + mix_str, test_wav], check=True)     print(f"🏆 V52.1 尾音保全版已就绪：{test_wav}")  if __name__ == "__main__":     run_v52_breath_protector()
